  briefing_layouts: { category: "B", userRefColumns: ["user_id"], piiRisk: "low", rlsStatus: "enabled", specialHandling: "Per-user Briefing layout envelope (Briefing Initiative B2). Whitelisted module ids only — no PII, no domain data. Reaper deletes explicitly (the users row is tombstoned, so CASCADE never fires). Excluded from the data-rights export like all preference objects." },
